def library_questions_q(prefix):
    # Same rule as services.library_questions_q (migrations can't import app code that may change).
    return (
        Q(**{f"{prefix}author__isnull": True})
        | Q(**{f"{prefix}author__role": "admin"})
        | Q(**{f"{prefix}author__is_superuser": True})
    )


def teacher_content_is_free(apps, schema_editor):
    """Quizzes teachers wrote in the app are their school's own work, so they stay open, unless they
    reuse questions from the premium library (services.quiz_is_teacher_material)."""
    Quiz = apps.get_model("assessments", "Quiz")
    Quiz.objects.filter(author__role="teacher").exclude(
        pk__in=Quiz.objects.filter(library_questions_q("quiz_questions__question__")).values("pk")
    ).update(is_free=True)



